import { ajax, Dom, Event, Loc, Tag, Text, Type } from 'main.core';
import { EventEmitter } from 'main.core.events';
import { FocusMonitor, FocusNavigator, LiveAnnouncer } from 'ui.a11y';
import 'ui.buttons';
import 'ui.icon-set.actions';
import 'ui.icon-set.main';
import 'ui.icons.b24';
import 'ui.icons.crm';
import { PopupComponentsMaker, PopupComponentsMakerItem } from 'ui.popupcomponentsmaker';
import { WidgetLoader } from 'intranet.widget-loader';
import { RequisiteSection } from './requisite-section';
import {
	type MainPageConfiguration,
	type SettingsWidgetHoldingOptions,
	type SettingsWidgetOptions,
} from './types/options';

export class SettingsWidget extends EventEmitter
{
	#widgetPopup: PopupComponentsMaker;
	#target: Element;

	#otp;
	static #instance = null;
	#marketUrl: string;
	#theme:? Object;
	#holding: ?SettingsWidgetHoldingOptions = null;
	#holdingWidget;
	#isBitrix24:? boolean = false;
	#isFreeLicense:? boolean = false;
	#isAdmin:? boolean;
	#requisite:? Object;
	#requisiteSection: RequisiteSection;
	#settingsUrl: string;
	#isRenameable:? boolean;
	#mainPage: MainPageConfiguration;

	constructor(options: SettingsWidgetOptions)
	{
		super();
		this.setEventNamespace('BX.Intranet.SettingsWidget');
		this.#marketUrl = options.marketUrl;
		this.#isBitrix24 = options.isBitrix24;
		this.#isFreeLicense = options.isFreeLicense;
		this.#isAdmin = options.isAdmin;
		this.#requisite = options.requisite;
		this.#settingsUrl = options.settingsPath;
		this.#isRenameable = options.isRenameable;
		this.#mainPage = options.mainPage;
		this.#requisiteSection = new RequisiteSection(
			options.requisite,
			() => this.getWidget().close(),
			() => this.getWidget().getPopup(),
		);

		this.#setOptions(options);
	}

	#setOptions(options)
	{
		options.theme ? (this.#theme = options.theme) : null;
		options.otp ? (this.#otp = options.otp) : null;
		options.holding ? this.#setHoldingOptions(options.holding) : null;
	}

	#setHoldingOptions(options: SettingsWidgetHoldingOptions): void
	{
		if (!Type.isPlainObject(options))
		{
			this.#holding = null;
			return;
		}

		this.#holding = {
			isHolding: options.isHolding ?? false,
			affiliate: options.affiliate ?? null,
			canBeHolding: options.canBeHolding ?? false,
			canBeAffiliate: options.canBeAffiliate ?? false,
		};
	}

	setTarget(target)
	{
		this.#target = target;

		return this;
	}

	setWidgetLoader(widgetLoader: WidgetLoader)
	{
		this.#widgetPopup = new PopupComponentsMaker({
			width: 374,
			popupLoader: widgetLoader.getPopup(),
			useAngle: false,
		});

		this.#widgetPopup.getPopup().subscribe('onClose', () => {
			Event.unbindAll(this.getWidget().getPopup().getPopupContainer(), 'click');
			this.#updateAriaExpanded(false);
		});

		const popup = this.#widgetPopup.getPopup();
		const popupContainer = popup.getPopupContainer();
		const loadingFocusTarget = FocusNavigator.getActiveElement(popupContainer);
		const shouldSetInitialFocus = popup.isShown()
			&& FocusMonitor.Instance.getLastInputModality() === 'keyboard'
			&& loadingFocusTarget !== null
			&& popupContainer.contains(loadingFocusTarget)
		;

		widgetLoader.clearBeforeInsertContent();
		this.#getItemsList()
			.then(() => {
				this.#drawItemsList();
				const currentFocusTarget = FocusNavigator.getActiveElement(popupContainer);
				if (
					shouldSetInitialFocus
					&& popup.isShown()
					&& currentFocusTarget !== null
					&& currentFocusTarget === loadingFocusTarget
					&& popupContainer.contains(currentFocusTarget)
				)
				{
					FocusNavigator.focusContainer(popupContainer);
				}
			})
		;

		return this;
	}

	static bindWidget(widgetLoader: WidgetLoader): ?SettingsWidget
	{
		const instance = this.getInstance();

		if (instance)
		{
			instance.setWidgetLoader(widgetLoader);
		}

		return instance;
	}

	static bind(button): ?SettingsWidget
	{
		const instance = this.getInstance();

		if (instance)
		{
			Event.unbindAll(button);
			Event.bind(button, 'click', instance.toggle.bind(instance, button));
		}

		return instance;
	}

	static bindAndShow(button): ?SettingsWidget
	{
		const instance = this.bind(button);

		if (instance)
		{
			instance.show(button);
		}

		return instance;
	}

	static init(options): SettingsWidget
	{

		if (this.#instance === null)
		{
			this.#instance = new this(options);
		}
		return this.#instance;
	}

	static getInstance(): ?SettingsWidget
	{
		return this.#instance;
	}

	static close(): void
	{
		const instance = this.getInstance();

		if (instance)
		{
			instance.getWidget().close();
		}
	}

	toggle(targetNode)
	{
		const popup = this.getWidget().getPopup();
		if (popup.isShown())
		{
			popup.close();
			this.#updateAriaExpanded(false);
		}
		else
		{
			this.show(targetNode);
		}
	}

	show(targetNode): void
	{
		const popup = this.getWidget().getPopup();

		popup.setBindElement(targetNode);
		popup.show();

		if (popup.getPopupContainer().getBoundingClientRect().left < 30)
		{
			Dom.style(popup.getPopupContainer(), { left: '30px' });
		}

		this.setTarget(targetNode);
		this.#updateAriaExpanded(true);
	}

	getWidget(): PopupComponentsMaker
	{
		return this.#widgetPopup;
	}

	#getItemsList(reload: boolean = false): Promise
	{
		if (reload === true || typeof this.#theme === 'undefined')
		{
			return new Promise((resolve) => {
				ajax.runComponentAction('bitrix:intranet.settings.widget', 'getData', { mode: 'class' })
					.then(({ data: { theme, otp, holding } }) => {
						this.#theme = theme;
						this.#otp = otp;
						this.#setHoldingOptions(holding);
						resolve();
					})
				;
			});
		}

		return Promise.resolve();
	}

	#drawItemsList(): void
	{
		const container = this.getWidget().getPopup().getPopupContainer();

		Dom.append(this.#getHeader(), container);

		const content = [
			this.#requisite && this.#isAdmin ? this.#getRequisitesElement() : null,
			this.#mainPage.isAvailable ? this.#getMainPageElement() : null,
			this.#isAdmin ? this.#getSecurityAndSettingsElement() : null,
			this.#isBitrix24 ? this.#getHoldingsElement() : null,
			this.#isAdmin ? this.#getMigrateElement() : null,
		];

		content.forEach((element) => {
			Dom.append(element, container);
		});

		if (this.#isAdmin)
		{
			Dom.append(this.#getFooter(), container);
		}
	}

	#getLinkHeaderIcon(): HTMLElement
	{
		const onclickCopyLink = () => {
			if (BX.clipboard.copy(window.location.origin))
			{
				const message = Loc.getMessage('INTRANET_SETTINGS_WIDGET_LINK_COPIED_POPUP');
				BX.UI.Notification.Center.notify({
					content: message,
					position: 'top-left',
					autoHideDelay: 3000,
				});
				LiveAnnouncer.announce(message, 'polite');
			}
		};

		return Tag.render`
			<button
				type="button"
				class="intranet-settings-widget__header-btn"
				aria-label="${Loc.getMessage('INTRANET_SETTINGS_WIDGET_COPY_PORTAL_LINK_ARIA')}"
				data-autofocus
				data-testid="settings-widget-copy-link"
				onclick="${onclickCopyLink}"
			>
				<span class="ui-icon-set --link-3" aria-hidden="true"></span>
			</button>
		`;
	}

	#getEditHeaderIcon(): HTMLElement
	{
		const settingsUrl = `${this.#settingsUrl}?analyticContext=widget_settings_settings&page=portal&option=subDomainName`;
		const onclickEditLink = this.#openSidePanel.bind(this, settingsUrl);

		return Tag.render`
			<a
				class="intranet-settings-widget__header-btn"
				href="${settingsUrl}"
				aria-label="${Loc.getMessage('INTRANET_SETTINGS_WIDGET_RENAME_PORTAL_ARIA')}"
				data-autofocus
				data-testid="settings-widget-rename"
				onclick="${onclickEditLink}"
			>
				<span class="ui-icon-set --pencil-40" aria-hidden="true"></span>
			</a>
		`;
	}

	#getHeader(): HTMLElement
	{
		const header = Tag.render`
				<div class="intranet-settings-widget__header">
					<div class="intranet-settings-widget__header_inner">
						<span class="intranet-settings-widget__header-name">${window.location.host}</span>
						${this.#isRenameable ? this.#getEditHeaderIcon() : this.#getLinkHeaderIcon()}
					</div>
				</div>
			`;
		this.#applyTheme(header, this.#theme);

		const adaptedEmptyHeader = (new PopupComponentsMakerItem({
			withoutBackground: true,
			html: header,
		})).getContainer();
		Dom.addClass(adaptedEmptyHeader, '--widget-header');

		EventEmitter.subscribe(
			'BX.Intranet.Bitrix24:ThemePicker:onThemeApply',
			({ data: { theme } }) =>
			{
				this.#applyTheme(header, theme);
			},
		);

		return adaptedEmptyHeader;
	}

	#applyTheme(container, theme): void
	{
		const previewImage = `url('${Text.encode(theme.previewImage)}')`;
		Dom.style(container, 'backgroundImage', previewImage);

		Dom.removeClass(container, 'bitrix24-dark-theme bitrix24-light-theme');
		const themeClass = String(theme.id).indexOf('dark:') === 0 ? 'bitrix24-dark-theme' : 'bitrix24-light-theme';
		Dom.addClass(container, themeClass);
	}

	#getFooter(): HTMLElement
	{
		const onclickOpenPartnerOrder = () => {
			this.getWidget().close();
			BX.UI.InfoHelper.show('info_implementation_request');
		};

		const partnerOrder = Tag.render`
			<button
				type="button"
				class="intranet-settings-widget__footer-item"
				data-testid="settings-widget-order"
				onclick="${onclickOpenPartnerOrder}"
			>
				${Loc.getMessage('INTRANET_SETTINGS_WIDGET_ORDER_PARTNER_LINK_MSGVER_1')}
			</button>
		`;

		const onclickWhereToBegin = () => {
			if (top.BX.Helper)
			{
				this.getWidget().close();
				top.BX.Helper.show('redirect=detail&code=18371844');
			}
		};

		const onclickSupport = () => {
			if (top.BX.Helper)
			{
				this.getWidget().close();
				if (this.#isFreeLicense)
				{
					BX.UI.InfoHelper.show('limit_support_bitrix');
				}
				else
				{
					BX.Helper.show('redirect=detail&code=12925062');
				}
			}
		};

		return Tag.render`
				<div class="intranet-settings-widget__footer">
					${this.#isBitrix24 ? partnerOrder : ''}
					<button
						type="button"
						class="intranet-settings-widget__footer-item"
						data-testid="settings-widget-getting-started"
						onclick="${onclickWhereToBegin}"
					>
						${Loc.getMessage('INTRANET_SETTINGS_WIDGET_WHERE_TO_BEGIN_LINK')}
					</button>
					<button
						type="button"
						class="intranet-settings-widget__footer-item"
						data-testid="settings-widget-support"
						onclick="${onclickSupport}"
					>
						${Loc.getMessage('INTRANET_SETTINGS_WIDGET_SUPPORT_BUTTON')}
					</button>
				</div>
			`;
	}

	#prepareElement(element): HTMLElement
	{
		const item = this.getWidget().getItem({ html: element });
		const node = item.getContainer();
		Dom.addClass(node, '--widget-item');

		return node;
	}

	#openSidePanel(url: string, event): void
	{
		if (event.ctrlKey || event.metaKey)
		{
			return;
		}

		event.preventDefault();
		this.getWidget().close();
		BX.SidePanel.Instance.open(url);
	}

	#getMainPageElement(): HTMLElement
	{
		const onclick = this.#openSidePanel.bind(this, this.#mainPage.settingsPath);

		const element = Tag.render`
			<a
				class="intranet-settings-widget_box --clickable"
				href="${this.#mainPage.settingsPath}"
				data-testid="settings-widget-main-page"
				onclick="${onclick}"
			>
				<span class="intranet-settings-widget_inner">
					<span class="intranet-settings-widget_icon-box --green">
						<span class="ui-icon-set --home-page" aria-hidden="true"></span>
					</span>
					<span class="intranet-settings-widget__title">
						${Loc.getMessage('INTRANET_SETTINGS_WIDGET_WELCOME_PAGE_TITLE')}
					</span>
				</span>
				<span class="intranet-settings-widget__arrow-btn ui-icon-set --arrow-right" aria-hidden="true"></span>
			</a>
		`;

		return this.#prepareElement(element);
	}

	#getRequisitesElement(): HTMLDivElement
	{
		return this.#prepareElement(this.#requisiteSection.getElement());
	}

	#getHoldingsElement(): ?HTMLDivElement
	{
		if (this.#isBitrix24 !== true || this.#holding === null)
		{
			return null;
		}

		if (!Type.isPlainObject(this.#holding.affiliate))
		{
			return this.#getEmptyHoldingsElement();
		}

		const affiliate = this.#holding.affiliate;
		const onclickOpen = () => {
			this.getWidget().close();
			this.#getHoldingWidget().show(this.#target);
		};

		const element = Tag.render`
			<button
				type="button"
				class="intranet-settings-widget__branch"
				data-testid="settings-widget-affiliate"
				onclick="${onclickOpen}"
			>
					<span class="intranet-settings-widget__branch-icon_box">
						<span class="ui-icon-set intranet-settings-widget__branch-icon --filial-network" aria-hidden="true"></span>
					</span>
					<span class="intranet-settings-widget__branch_content">
						<span class="intranet-settings-widget__branch-title">
							${
								affiliate.isHolding
									? Loc.getMessage('INTRANET_SETTINGS_WIDGET_MAIN_BRANCH')
									: Loc.getMessage('INTRANET_SETTINGS_WIDGET_SECONDARY_BRANCH')
							}
						</span>
						<span class="intranet-settings-widget__title">
							${affiliate.name}
						</span>
					</span>
					<span class="intranet-settings-widget__branch-btn_box">
						<span class="ui-btn ui-btn-light-border ui-btn-round ui-btn-xs ui-btn-no-caps intranet-setting__btn-light">
							${Loc.getMessage('INTRANET_SETTINGS_WIDGET_BRANCHES')}
						</span>
					</span>
				</button>
			`;

		return this.#prepareElement(element);
	}

	#getHoldingWidget()
	{
		if (!this.#holdingWidget)
		{
			this.#holdingWidget = BX.Intranet.HoldingWidget.getInstance();

			const onclickClose = () => {
				this.#holdingWidget.getWidget().close();
				this.show(this.#target);
			};

			const holdingWidgetCloseBtn = Tag.render`
				<button
					type="button"
					class="intranet-settings-widget__close-btn"
					data-testid="settings-widget-holding-back"
					onclick="${onclickClose}"
				>
					<span aria-hidden="true" class="ui-icon-set --arrow-left intranet-settings-widget__close-btn_icon"></span>
					<span class="intranet-settings-widget__close-btn_name">
						${Loc.getMessage('INTRANET_SETTINGS_WIDGET_BRANCH_LIST')}
					</span>
				</button>
			`;

			this.#holdingWidget.getWidget().getPopup().getContentContainer().prepend(holdingWidgetCloseBtn);
		}

		return this.#holdingWidget;
	}

	#getEmptyHoldingsElement(): ?HTMLDivElement
	{
		if (!Type.isPlainObject(this.#holding))
		{
			return null;
		}

		const title = this.#isAdmin
			? Loc.getMessage('INTRANET_SETTINGS_WIDGET_FILIAL_NETWORK')
			: Loc.getMessage('INTRANET_SETTINGS_WIDGET_FILIAL_NETWORK_UNAVAILABLE')
		;

		const buttonText = this.#isAdmin
			? Loc.getMessage('INTRANET_SETTINGS_WIDGET_FILIAL_SETTINGS')
			: Loc.getMessage('INTRANET_SETTINGS_WIDGET_FILIAL_ABOUT')
		;

		const onclickOpen = () => {
			this.getWidget().close();
			if (this.#holding.canBeHolding)
			{
				this.#getHoldingWidget().show(this.#target);
			}
			else
			{
				BX.UI.InfoHelper.show('limit_office_multiple_branches');
			}
		};

		const lockIcon = Tag.render`
			<span class="intranet-settings-widget__branch-lock-icon_box">
				<span class="ui-icon-set intranet-settings-widget__branch-lock-icon --lock" aria-hidden="true"></span>
			</span>
		`;

		const element = Tag.render`
			<button
				type="button"
				class="intranet-settings-widget__branch"
				data-testid="settings-widget-holding"
				onclick="${onclickOpen}"
			>
				<span class="intranet-settings-widget__branch-icon_box">
					<span class="ui-icon-set intranet-settings-widget__branch-icon --filial-network" aria-hidden="true"></span>
					${!this.#holding.canBeHolding ? lockIcon : ''}
				</span>
				<span class="intranet-settings-widget__branch_content">
					<span class="intranet-settings-widget__title">${title}</span>
				</span>
				<span class="intranet-settings-widget__branch-btn_box">
					<span
						class="ui-btn ui-btn-light-border ui-btn-round ui-btn-xs ui-btn-no-caps intranet-setting__btn-light"
					>
						${buttonText}
					</span>
				</span>
			</button>
		`;

		return this.#prepareElement(element);
	}

	#getSecurityAndSettingsElement(): HTMLDivElement
	{
		return Tag.render`
			<div class="intranet-settings-widget_inline-box">
				${this.#getSecurityElement()}
				${this.#getGeneralSettingsElement()}
			</div>
		`;
	}

	#getSecurityElement(): HTMLElement
	{
		const settingsUrl = `${this.#settingsUrl}?page=security&analyticContext=widget_settings_settings`;
		const onclick = this.#openSidePanel.bind(this, settingsUrl);

		const element = Tag.render`
			<a
				class="intranet-settings-widget_box --clickable"
				href="${settingsUrl}"
				data-testid="settings-widget-security"
				onclick="${onclick}"
			>
				<span class="intranet-settings-widget_inner">
					<span class="intranet-settings-widget_icon-box ${this.#otp.IS_ACTIVE === 'Y' ? '--green' : '--yellow'}">
						<span class="ui-icon-set --shield" aria-hidden="true"></span>
					</span>
					<span class="intranet-settings-widget__title">
						${Loc.getMessage('INTRANET_SETTINGS_WIDGET_SECTION_SECURITY_TITLE')}
					</span>
				</span>
				<span class="intranet-settings-widget__arrow-btn ui-icon-set --arrow-right" aria-hidden="true"></span>
			</a>
		`;

		return this.#prepareElement(element);
	}

	#getGeneralSettingsElement(): HTMLElement
	{
		const settingsUrl = `${this.#settingsUrl}?analyticContext=widget_settings_settings`;
		const onclick = this.#openSidePanel.bind(this, settingsUrl);

		const element = Tag.render`
			<a
				class="intranet-settings-widget_box --clickable"
				href="${settingsUrl}"
				data-testid="settings-widget-general"
				onclick="${onclick}"
			>
				<span class="intranet-settings-widget_inner">
					<span class="intranet-settings-widget_icon-box --gray">
						<span class="ui-icon-set --settings-2" aria-hidden="true"></span>
					</span>
					<span class="intranet-settings-widget__title">
						${Loc.getMessage('INTRANET_SETTINGS_WIDGET_SECTION_SETTINGS_TITLE')}
					</span>
				</span>
				<span class="intranet-settings-widget__arrow-btn ui-icon-set --arrow-right" aria-hidden="true"></span>
			</a>
		`;

		return this.#prepareElement(element);
	}

	#getMigrateElement(): HTMLElement
	{
		const marketUrl = `${this.#marketUrl}category/migration/`;
		const onclick = this.#openSidePanel.bind(this, marketUrl);

		const element = Tag.render`
			<a
				class="intranet-settings-widget_box --clickable"
				href="${marketUrl}"
				data-testid="settings-widget-migrate"
				onclick="${onclick}"
			>
				<span class="intranet-settings-widget_inner">
					<span class="intranet-settings-widget_icon-box --gray">
						<span class="ui-icon-set --market-1" aria-hidden="true"></span>
					</span>
					<span class="intranet-settings-widget__title">
						${Loc.getMessage('INTRANET_SETTINGS_WIDGET_SECTION_MIGRATION_TITLE')}
					</span>
				</span>
				<span class="intranet-settings-widget__arrow-btn ui-icon-set --arrow-right" aria-hidden="true"></span>
			</a>
		`;

		return this.#prepareElement(element);
	}

	#updateAriaExpanded(expanded: boolean): void
	{
		if (this.#target)
		{
			Dom.attr(this.#target, 'aria-expanded', expanded);
		}
	}
}
